"use client";

import { useEffect, useMemo, useRef, useSyncExternalStore, type CSSProperties, type PointerEvent } from "react";
import { motion, useMotionValue, useReducedMotion, useSpring, useTransform, type MotionValue } from "framer-motion";
import { cn } from "@/lib/utils";
import { BJORK_PALETTE, type BjorkTone } from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { VisuallyHidden } from "@/components/bjork-ui/_core/a11y";
import { isCoarsePointer, useVisibleLoop } from "@/components/bjork-ui/_core/loop";

export type PlaneTypeVariant = "solid" | "mixed" | "outline";
export type PlaneTypePointerSource = "self" | "window" | "scroll" | "none";
export type PlaneTypeAlign = "left" | "center" | "right";

export interface PlaneTypeProps {
  lines: string[];
  as?: "h1" | "h2" | "h3";
  size?: string;
  depth?: number;
  tilt?: number;
  slide?: number;
  overlap?: number;
  skew?: number;
  variant?: PlaneTypeVariant;
  knockout?: boolean;
  pointerSource?: PlaneTypePointerSource;
  align?: PlaneTypeAlign;
  opticalAlign?: boolean;
  spring?: { stiffness: number; damping: number; mass: number };
  /** Fixed normalised pointer position, for deterministic previews. Overrides pointer input. */
  pose?: { x: number; y: number };
  tone?: BjorkTone;
  attract?: boolean;
  className?: string;
}

const MAX_LINES = 6;
// Cap height of the display face in em (Bjork Grotesk Display 700, H/M/I/E/T). Measured by blur test.
const CAP_HEIGHT = 0.71; // em
// Perspective distance in px. Planes are counter-scaled against it so they sit flat at rest.
const PERSPECTIVE = 900;
const OUTLINE_STROKE = "1.5px";
const subscribeNoop = () => () => {};
const DEFAULT_SPRING = { stiffness: 150, damping: 20, mass: 1 };
const ATTRACT_IDLE_MS = 4000;
const ATTRACT_AMPLITUDE = 0.6;
const ATTRACT_PERIOD_X = 7;
const ATTRACT_PERIOD_Y = 11;

// Optical left-edge offsets, in em. The right edge mirrors these values.
const OPTICAL_EM: Record<string, number> = {
  O: -0.04,
  Q: -0.04,
  C: -0.03,
  G: -0.03,
  S: -0.02,
  A: -0.02,
  V: -0.02,
  W: -0.02,
  T: -0.02,
  Y: -0.02,
};

function opticalOffset(line: string, align: PlaneTypeAlign): number {
  if (align === "center") return 0;
  const trimmed = line.trim();
  if (!trimmed) return 0;
  const edge = align === "right" ? trimmed.charAt(trimmed.length - 1) : trimmed.charAt(0);
  const value = OPTICAL_EM[edge.toUpperCase()] ?? 0;
  return align === "right" ? -value : value;
}

function clamp(v: number) {
  return Math.max(-1, Math.min(1, v));
}

function subscribeCoarse(onChange: () => void) {
  const query = window.matchMedia("(pointer: coarse)");
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

interface Paint {
  color: string;
  outline: boolean;
  blend: "normal" | "difference" | "multiply";
}

function paintFor(index: number, variant: PlaneTypeVariant, knockout: boolean, tone: BjorkTone): Paint {
  const kind =
    variant === "outline" ? "outline" : variant === "solid" ? "solid" : (["solid", "accent", "outline"] as const)[index % 3];
  const text = "var(--bjork-text)";
  const accent = "var(--bjork-accent)";
  if (knockout) {
    const color = tone === "dark" ? text : index % 2 === 0 ? text : accent;
    return { color, outline: kind === "outline", blend: tone === "dark" ? "difference" : "multiply" };
  }
  return { color: kind === "accent" ? accent : text, outline: kind === "outline", blend: "normal" };
}

interface PlaneProps {
  text: string;
  index: number;
  count: number;
  depth: number;
  skew: number;
  overlap: number;
  opticalEm: number;
  originEm: number;
  reduce: boolean;
  shift: MotionValue<number>;
  paint: Paint;
  align: PlaneTypeAlign;
}

// Each plane's transform is built once per instance. Every constant it closes over is part of the key in PlaneType.
function Plane({ text, index, count, depth, skew, overlap, opticalEm, originEm, reduce, shift, paint, align }: PlaneProps) {
  const mid = (count - 1) / 2;
  const dx = index - mid;
  const z = dx * depth;
  const k = (PERSPECTIVE - z) / PERSPECTIVE;
  const rotation = reduce ? 0 : (index % 2 ? 1 : -1) * skew;
  const y = index * (CAP_HEIGHT - overlap);
  const transform = useTransform(
    shift,
    (v: number) =>
      `translateX(calc(${opticalEm * k}em + ${(v * dx * k).toFixed(3)}px)) translateY(${y * k}em) translateZ(${z}px) scale(${k}) rotateZ(${rotation}deg)`,
  );

  const textAlign = align === "center" ? "text-center" : align === "right" ? "text-right" : "text-left";
  const style: CSSProperties = paint.outline
    ? { color: "transparent", WebkitTextStroke: `${OUTLINE_STROKE} ${paint.color}`, mixBlendMode: paint.blend }
    : { color: paint.color, WebkitTextStroke: "0", mixBlendMode: paint.blend };

  return (
    <motion.span
      aria-hidden="true"
      className={cn(
        "pointer-events-none block w-full self-start whitespace-nowrap font-bjork-display font-bold leading-[0.82] tracking-[-0.04em] [grid-area:1/1] [text-box:trim-both_cap_alphabetic]",
        textAlign,
      )}
      style={{ ...style, transform, transformOrigin: `50% ${originEm}em` }}
    >
      {text || " "}
    </motion.span>
  );
}

/**
 * Display type set as overlapping planes in 3D space. The whole stack tilts with the pointer,
 * and each plane slides against the others, so the lines pass each other as you move.
 */
export function PlaneType({
  lines,
  as = "h2",
  size = "clamp(48px, 9vw, 128px)",
  depth = 48,
  tilt = 8,
  slide = 6,
  overlap = 0.18,
  skew = 0,
  variant = "mixed",
  knockout = false,
  pointerSource = "self",
  align = "left",
  opticalAlign = true,
  spring = DEFAULT_SPRING,
  pose,
  tone: toneProp,
  attract = false,
  className,
}: PlaneTypeProps) {
  const tone = useBjorkTone(toneProp);
  const palette = BJORK_PALETTE[tone];
  // Server and first client render both report "not reduced", so reduced motion only applies after hydration.
  const hydrated = useSyncExternalStore(subscribeNoop, () => true, () => false);
  const prefersReduced = useReducedMotion();
  const reduce = hydrated && prefersReduced === true;
  const rootRef = useRef<HTMLDivElement>(null);
  const shown = lines.slice(0, MAX_LINES);
  const count = shown.length;
  const coarse = useSyncExternalStore(subscribeCoarse, isCoarsePointer, () => false);
  // Touch devices cannot hover, so "self" falls back to "scroll".
  const source: PlaneTypePointerSource = pointerSource === "self" && coarse ? "scroll" : pointerSource;

  const hasPose = pose !== undefined;
  const poseX = pose?.x ?? 0;
  const poseY = pose?.y ?? 0;

  // Raw targets are already in rendered units: degrees for the tilt, px for the slide.
  const rotX = useMotionValue(hasPose && !reduce ? -poseY * tilt : 0);
  const rotY = useMotionValue(hasPose && !reduce ? poseX * tilt : 0);
  const shift = useMotionValue(hasPose && !reduce ? poseX * slide : 0);

  const springConfig = useMemo(
    () => ({ stiffness: spring.stiffness, damping: spring.damping, mass: spring.mass }),
    [spring.stiffness, spring.damping, spring.mass],
  );
  const rotXs = useSpring(rotX, springConfig);
  const rotYs = useSpring(rotY, springConfig);
  const shiftS = useSpring(shift, springConfig);

  const aim = (nx: number, ny: number) => {
    if (reduce) {
      rotX.set(0);
      rotY.set(0);
      shift.set(0);
      return;
    }
    const x = clamp(nx);
    const y = clamp(ny);
    rotX.set(-y * tilt);
    rotY.set(x * tilt);
    shift.set(x * slide);
  };
  const aimRef = useRef(aim);
  useEffect(() => {
    aimRef.current = aim;
  });

  // Pose and reduced motion both replace the pointer's target.
  useEffect(() => {
    if (reduce) aimRef.current(0, 0);
    else if (hasPose) aimRef.current(poseX, poseY);
  }, [reduce, hasPose, poseX, poseY]);

  const lastInput = useRef(Number.NEGATIVE_INFINITY);
  const rect = useRef<DOMRect | null>(null);

  const onPointerEnter = () => {
    if (source !== "self") return;
    rect.current = rootRef.current?.getBoundingClientRect() ?? null;
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (source !== "self") return;
    lastInput.current = performance.now();
    const r = rect.current ?? rootRef.current?.getBoundingClientRect();
    if (!r || r.width === 0 || r.height === 0) return;
    rect.current = r;
    aim(((event.clientX - r.left) / r.width) * 2 - 1, ((event.clientY - r.top) / r.height) * 2 - 1);
  };

  const onPointerLeave = () => {
    if (source !== "self") return;
    rect.current = null;
    aim(0, 0);
  };

  // Window and scroll sources only listen while the component is on screen.
  useEffect(() => {
    if (source !== "window" && source !== "scroll") return;
    const el = rootRef.current;
    if (!el) return;

    const onWindowMove = (event: globalThis.PointerEvent) => {
      lastInput.current = performance.now();
      aimRef.current((event.clientX / window.innerWidth) * 2 - 1, (event.clientY / window.innerHeight) * 2 - 1);
    };
    const onWindowOut = (event: globalThis.PointerEvent) => {
      if (!event.relatedTarget) aimRef.current(0, 0);
    };
    const onScroll = () => {
      lastInput.current = performance.now();
      const r = el.getBoundingClientRect();
      const half = window.innerHeight / 2;
      const centre = r.top + r.height / 2;
      aimRef.current(0, (half - centre) / half);
    };

    let attached = false;
    const attach = () => {
      if (attached) return;
      attached = true;
      if (source === "window") {
        window.addEventListener("pointermove", onWindowMove, { passive: true });
        window.addEventListener("pointerout", onWindowOut, { passive: true });
      } else {
        window.addEventListener("scroll", onScroll, { passive: true });
        window.addEventListener("resize", onScroll, { passive: true });
        onScroll();
      }
    };
    const detach = () => {
      if (!attached) return;
      attached = false;
      window.removeEventListener("pointermove", onWindowMove);
      window.removeEventListener("pointerout", onWindowOut);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };

    const observer = new IntersectionObserver(([entry]) => {
      if (entry?.isIntersecting) attach();
      else detach();
    });
    observer.observe(el);
    return () => {
      observer.disconnect();
      detach();
    };
  }, [source]);

  // Idle drift: a Lissajous path feeds the springs. Any input inside the component pauses it for 4s.
  const attractOn = attract && !reduce && !hasPose && source !== "none";
  const attractT = useRef(0);
  useVisibleLoop(
    rootRef,
    (dt) => {
      if (performance.now() - lastInput.current < ATTRACT_IDLE_MS) return;
      attractT.current += dt;
      const t = attractT.current;
      aimRef.current(
        ATTRACT_AMPLITUDE * Math.sin((2 * Math.PI * t) / ATTRACT_PERIOD_X),
        ATTRACT_AMPLITUDE * Math.sin((2 * Math.PI * t) / ATTRACT_PERIOD_Y),
      );
    },
    { enabled: attractOn },
  );

  useEffect(() => {
    if (count > 0 && lines.length > MAX_LINES) {
      console.warn(`PlaneType renders up to ${MAX_LINES} lines; ${lines.length} were given.`);
    }
  }, [lines.length, count]);

  const cssVars = { "--bjork-text": palette.text, "--bjork-accent": palette.accent } as CSSProperties;
  const justifyRow = align === "center" ? "justify-center" : align === "right" ? "justify-end" : "justify-start";
  const totalEm = count > 0 ? (count - 1) * (CAP_HEIGHT - overlap) + CAP_HEIGHT : 0;
  const originEm = totalEm / 2;
  const Tag = as;

  return (
    <div
      ref={rootRef}
      className={cn("relative w-full select-none", className)}
      style={{
        ...cssVars,
        perspective: `${PERSPECTIVE}px`,
        isolation: "isolate",
        fontSize: size,
        backgroundColor: knockout ? palette.stage : undefined,
      }}
      onPointerEnter={onPointerEnter}
      onPointerMove={onPointerMove}
      onPointerLeave={onPointerLeave}
    >
      <motion.div
        className={cn("flex w-full", justifyRow)}
        style={{ rotateX: rotXs, rotateY: rotYs, transformStyle: "preserve-3d" }}
      >
        <Tag className="m-0 w-full font-bjork-display" style={{ transformStyle: "preserve-3d" }}>
          <VisuallyHidden>{shown.join(" ")}</VisuallyHidden>
          <span aria-hidden="true" className="grid w-full" style={{ transformStyle: "preserve-3d" }}>
            <span aria-hidden="true" className="invisible [grid-area:1/1]" style={{ height: `${totalEm}em` }} />
            {shown.map((line, index) => {
              const opticalEm = opticalAlign ? opticalOffset(line, align) : 0;
              return (
                <Plane
                  key={`${index}|${count}|${depth}|${skew}|${overlap}|${opticalEm}|${originEm}|${reduce ? 1 : 0}`}
                  text={line}
                  index={index}
                  count={count}
                  depth={depth}
                  skew={skew}
                  overlap={overlap}
                  opticalEm={opticalEm}
                  originEm={originEm}
                  reduce={reduce}
                  shift={shiftS}
                  paint={paintFor(index, variant, knockout, tone)}
                  align={align}
                />
              );
            })}
          </span>
        </Tag>
      </motion.div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import type { BjorkTone } from "./palette";

const subscribeNoop = () => () => {};
const getMounted = () => true;
const getServerMounted = () => false;

/**
 * Resolves the tone for a component. An explicit `tone` always wins.
 * Otherwise it follows next-themes' resolved theme, but only after mount,
 * so the server render and first client render agree on dark.
 */
export function useBjorkTone(tone?: BjorkTone): BjorkTone {
  const { resolvedTheme } = useTheme();
  const mounted = useSyncExternalStore(subscribeNoop, getMounted, getServerMounted);
  if (tone) return tone;
  if (!mounted) return "dark";
  return resolvedTheme === "light" ? "light" : "dark";
}

import type { ReactNode } from "react";

// Text for assistive tech only.
export function VisuallyHidden({ children }: { children: ReactNode }) {
  return <span className="sr-only">{children}</span>;
}

// Announces `message` when it changes. Same text re-rendered does not re-announce.
export function LiveRegion({
  message,
  politeness = "polite",
}: {
  message: string;
  politeness?: "polite" | "assertive";
}) {
  return (
    <span role="status" aria-live={politeness} aria-atomic="true" className="sr-only">
      {message}
    </span>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}
